// Session auth for the single shared operator login.
//
// Uses the Web Crypto API only (no Node `crypto` import) so this module can be
// imported from both the Edge middleware and Node route handlers. The session
// is a stateless HMAC-signed token stored in an HttpOnly cookie.

export const SESSION_COOKIE = 'smg_session'
export const SESSION_MAX_AGE_SECONDS = 60 * 60 * 24 * 30 // 30 days

const encoder = new TextEncoder()

function getSecret(): string | null {
  const secret = process.env.AUTH_SECRET
  return secret && secret.length > 0 ? secret : null
}

/** True only when both the signing secret and the operator password are set. */
export function isAuthConfigured(): boolean {
  return Boolean(getSecret() && process.env.APP_PASSWORD)
}

function bytesToBase64Url(bytes: Uint8Array): string {
  let binary = ''
  for (const b of bytes) binary += String.fromCharCode(b)
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

function base64UrlToBytes(input: string): Uint8Array {
  const b64 = input.replace(/-/g, '+').replace(/_/g, '/') + '=='.slice((input.length + 3) % 4)
  const binary = atob(b64)
  const out = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i)
  return out
}

async function hmacKey(secret: string): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    'raw',
    encoder.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign', 'verify']
  )
}

interface SessionPayload {
  iat: number
  exp: number
}

/** Create a signed session token. Throws if AUTH_SECRET is not configured. */
export async function createSessionToken(): Promise<string> {
  const secret = getSecret()
  if (!secret) throw new Error('AUTH_SECRET is not configured')

  const now = Date.now()
  const payload: SessionPayload = { iat: now, exp: now + SESSION_MAX_AGE_SECONDS * 1000 }
  const payloadB64 = bytesToBase64Url(encoder.encode(JSON.stringify(payload)))

  const key = await hmacKey(secret)
  const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(payloadB64))

  return `${payloadB64}.${bytesToBase64Url(new Uint8Array(signature))}`
}

/** Verify a session token's signature and expiry. Returns false on any problem. */
export async function verifySessionToken(token: string | undefined | null): Promise<boolean> {
  const secret = getSecret()
  if (!secret || !token) return false

  const parts = token.split('.')
  if (parts.length !== 2) return false
  const [payloadB64, signatureB64] = parts

  try {
    const key = await hmacKey(secret)
    const valid = await crypto.subtle.verify(
      'HMAC',
      key,
      base64UrlToBytes(signatureB64),
      encoder.encode(payloadB64)
    )
    if (!valid) return false

    const payload = JSON.parse(new TextDecoder().decode(base64UrlToBytes(payloadB64))) as SessionPayload
    return typeof payload.exp === 'number' && payload.exp > Date.now()
  } catch {
    return false
  }
}

/** Constant-time comparison of the supplied password against APP_PASSWORD. */
export function verifyPassword(input: string): boolean {
  const expected = process.env.APP_PASSWORD
  if (!expected || expected.length === 0) return false

  const a = encoder.encode(input)
  const b = encoder.encode(expected)
  if (a.length !== b.length) return false

  let diff = 0
  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i]
  return diff === 0
}

import { NextResponse, type NextRequest } from 'next/server'
import { SESSION_COOKIE, verifySessionToken } from '@/lib/auth'

// Paths reachable without a session. Everything else requires the operator login.
// - /login + /api/auth/login: the login surface itself.
// - /api/cron: authenticates itself with CRON_SECRET (called by an external
//   scheduler that has no session cookie), so it's excluded here and guarded
//   inside the route handler.
const PUBLIC_PATHS = new Set(['/login', '/api/auth/login', '/api/cron'])

export async function middleware(request: NextRequest): Promise<NextResponse> {
  const { pathname } = request.nextUrl

  if (PUBLIC_PATHS.has(pathname)) {
    return NextResponse.next()
  }

  const token = request.cookies.get(SESSION_COOKIE)?.value
  if (await verifySessionToken(token)) {
    return NextResponse.next()
  }

  // Unauthenticated: API routes get a JSON 401; page routes redirect to /login.
  if (pathname.startsWith('/api/')) {
    return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 })
  }

  const loginUrl = new URL('/login', request.url)
  return NextResponse.redirect(loginUrl)
}

export const config = {
  // Run on all routes except Next internals and static image assets.
  matcher: [
    '/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico)$).*)',
  ],
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import {
  createSessionToken,
  isAuthConfigured,
  verifyPassword,
  SESSION_COOKIE,
  SESSION_MAX_AGE_SECONDS,
} from '@/lib/auth'
import type { ApiResponse } from '@/types'

const BodySchema = z.object({ password: z.string().min(1) })

export async function POST(request: NextRequest): Promise<NextResponse> {
  if (!isAuthConfigured()) {
    const response: ApiResponse<never> = {
      success: false,
      error: 'Auth is not configured. Set AUTH_SECRET and APP_PASSWORD in the environment.',
    }
    return NextResponse.json(response, { status: 500 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    body = null
  }

  const parsed = BodySchema.safeParse(body)
  if (!parsed.success) {
    const response: ApiResponse<never> = { success: false, error: 'Password is required' }
    return NextResponse.json(response, { status: 400 })
  }

  if (!verifyPassword(parsed.data.password)) {
    const response: ApiResponse<never> = { success: false, error: 'Incorrect password' }
    return NextResponse.json(response, { status: 401 })
  }

  const token = await createSessionToken()
  const response: ApiResponse<never> = { success: true }
  const res = NextResponse.json(response)
  res.cookies.set(SESSION_COOKIE, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: SESSION_MAX_AGE_SECONDS,
  })
  return res
}

import { NextResponse } from 'next/server'
import { SESSION_COOKIE } from '@/lib/auth'
import type { ApiResponse } from '@/types'

export async function POST(): Promise<NextResponse> {
  const response: ApiResponse<never> = { success: true }
  const res = NextResponse.json(response)
  res.cookies.set(SESSION_COOKIE, '', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
  })
  return res
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { Lock } from 'lucide-react'

export default function LoginPage() {
  const router = useRouter()
  const [password, setPassword] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setError(null)
    setSubmitting(true)
    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password }),
      })
      const json = await res.json()
      if (!json.success) throw new Error(json.error ?? 'Login failed')
      router.push('/')
      router.refresh()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Login failed')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
      <div className="w-full max-w-sm">
        <div className="flex flex-col items-center mb-6">
          <div className="w-11 h-11 rounded-lg bg-blue-600 flex items-center justify-center mb-3">
            <Lock size={20} className="text-white" />
          </div>
          <h1 className="text-lg font-bold text-white">SMG Social Hub</h1>
          <p className="text-sm text-slate-500 mt-0.5">Sign in to continue</p>
        </div>

        <form
          onSubmit={handleSubmit}
          className="bg-slate-900 border border-slate-800 rounded-xl p-6 space-y-4 shadow-xl"
        >
          <div>
            <label className="block text-xs font-medium text-slate-400 mb-1.5">Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoFocus
              required
              placeholder="Enter operator password"
              className="w-full bg-slate-800 border border-slate-700 text-white text-sm rounded-md px-3 py-2.5 placeholder-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          {error && (
            <p className="text-red-400 text-xs bg-red-500/10 border border-red-500/20 rounded px-3 py-2">
              {error}
            </p>
          )}

          <button
            type="submit"
            disabled={submitting || !password}
            className="w-full bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white text-sm font-medium rounded-md px-4 py-2.5 transition-colors"
          >
            {submitting ? 'Signing inâ€¦' : 'Sign in'}
          </button>
        </form>
      </div>
    </div>
  )
}

